{
  "name": "opencode-plugin-update-kit",
  "version": "0.6.0",
  "description": "Auto-update kit for opencode plugins \u2014 detects new versions, installs them, and notifies the user. Handles concurrency when multiple plugins use it.",
  "type": "module",
  "files": [
    "index.ts"
  ],
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "bun build index.ts --target=bun --outdir /tmp/update-kit-check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "auto-update"
  ],
  "license": "MIT"
}
